<div class="page-heading"><div><div class="eyebrow">BETTER BUSINESS IS A CONVERSATION</div><h1>Your private inbox<span class="green">.</span></h1><p>Connect directly with your trading partners.</p></div></div><div class="inbox"><aside class="conversation-list"><?php foreach($conversations as $c):?><a class="conversation <?= (int)$c['id']===$id?'active':'' ?>" href="/messages?id=<?= $c['id'] ?>"><span class="avatar"><?= e(strtoupper(substr($c['other_name'],0,1))) ?></span><div><strong><?= e($c['other_name']) ?></strong><small><?= $c['order_id']?'Order #'.$c['order_id']:($c['product_id']?'Product conversation':'Business conversation') ?></small></div><?php if($c['unread']):?><span class="count"><?= $c['unread'] ?></span><?php endif;?></a><?php endforeach;?><?php if(!$conversations):?><div class="empty-state"><p>No conversations yet.</p><a href="/catalog">Find a supplier →</a></div><?php endif;?></aside><section class="chat-panel"><?php if($conversation):?><header><strong><?= e($conversation['product_name']??'Private business conversation') ?></strong><?php if($conversation['order_id']):?><a href="/order?id=<?= $conversation['order_id'] ?>">Order #<?= $conversation['order_id'] ?> →</a><?php endif;?><small>Only conversation participants can read these messages.</small></header><div class="message-list" data-conversation="<?= $id ?>" data-user="<?= $user['id'] ?>" data-page="<?= $page ?>"><?php foreach($messages as $m):?><article class="message <?= (int)$m['sender_id']===(int)$user['id']?'mine':'' ?>"><strong><?= e($m['sender']) ?></strong><p><?= nl2br(e($m['body'])) ?></p><small><?= e($m['created_at']) ?> UTC</small></article><?php endforeach;?></div><div class="pagination-row"><?php if($page>1):?><a href="/messages?id=<?= $id ?>&page=<?= $page-1 ?>">Newer messages</a><?php endif;?><?php if(count($messages)===40):?><a href="/messages?id=<?= $id ?>&page=<?= $page+1 ?>">Older messages</a><?php endif;?></div><form method="post" action="/messages/send" class="message-form"><?= csrf() ?><input type="hidden" name="id" value="<?= $id ?>"><label class="visually-hidden" for="message-body">Message</label><textarea id="message-body" name="body" maxlength="4000" rows="2" required placeholder="Write a message…"></textarea><button class="btn btn-primary">Send →</button><small class="poll-status" role="status">Updates automatically every 10 seconds</small></form><?php else:?><div class="empty-state"><h2>Start something good.</h2><p>Open a supplier profile to start a private conversation.</p></div><?php endif;?></section></div>
